#include "EmbeddedInterface.hpp"

#include <windows.h>
#include <filesystem>
#include <fstream>
#include <map>
#include <memory>
#include <mutex>
#include <string>
#include <system_error>
#include <vector>

#include "Compression.hpp"
#include "constants.h"

// Generated by CMakeLists.txt (TKMInterfaceTable.c): one row per Resources/TKMInterface file, then a null row
extern "C" const struct TKMEmbeddedFile { const char* name; const char* data; const size_t* len; const size_t* origLen; } TKMInterfaceFiles[];

namespace EmbeddedInterface
{
std::optional<std::string> Embedded(std::string_view name)
{
	// decompressed once per file and kept (the names file is ~1.2 MB)
	static std::mutex mutex;
	static std::map<std::string, std::string, std::less<>> cache;
	std::lock_guard lock(mutex);
	if (auto it = cache.find(name); it != cache.end()) return it->second;
	for (const TKMEmbeddedFile* f = TKMInterfaceFiles; f->name; ++f) {
		if (name != f->name) continue;
		std::unique_ptr<Byte[]> content((Byte*)CompressionUtils::RAW::LZMA::Decompress((Byte*)f->data, (int)*f->len, (int)*f->origLen));
		if (!content) return std::nullopt;
		return cache.emplace(std::string(name), std::string((const char*)content.get(), *f->origLen)).first->second;
	}
	return std::nullopt;
}

void Unpack()
{
	wchar_t exePath[MAX_PATH] = {};
	const DWORD n = GetModuleFileNameW(nullptr, exePath, MAX_PATH);
	if (n == 0 || n >= MAX_PATH) return;
	std::error_code ec;
	const std::filesystem::path exe(exePath);
	const auto dir = exe.parent_path() / INTERFACE_DATA_DIR;
	const auto exeTime = std::filesystem::last_write_time(exe, ec);
	const bool exeTimeOk = !ec;
	for (const TKMEmbeddedFile* f = TKMInterfaceFiles; f->name; ++f) {
		const auto content = Embedded(f->name);
		if (!content) continue;
		const auto path = dir / f->name;
		ec.clear();
		if (std::filesystem::exists(path, ec)) {
			// same bytes: nothing to do; edited after this exe was built: keep the user's file
			if (std::filesystem::file_size(path, ec) == content->size() && !ec) {
				std::ifstream in(path, std::ios::binary);
				std::string disk(content->size(), '\0');
				if (in.read(disk.data(), (std::streamsize)disk.size()) && disk == *content) continue;
			}
			ec.clear();
			const auto fileTime = std::filesystem::last_write_time(path, ec);
			if (!ec && exeTimeOk && fileTime > exeTime) continue;
		}
		std::filesystem::create_directories(dir, ec);
		std::ofstream out(path, std::ios::binary | std::ios::trunc);
		if (out) out.write(content->data(), (std::streamsize)content->size());
	}
}

std::optional<std::string> Read(std::string_view name)
{
	std::vector<std::filesystem::path> candidates{ std::filesystem::path(INTERFACE_DATA_DIR) / std::string(name) };
	wchar_t exe[32768];
	const DWORD n = GetModuleFileNameW(nullptr, exe, _countof(exe));
	if (n && n < _countof(exe)) candidates.push_back(std::filesystem::path(exe).parent_path() / INTERFACE_DATA_DIR / std::string(name));
	for (const auto& path : candidates) {
		std::error_code ec;
		if (!std::filesystem::is_regular_file(path, ec)) continue;
		std::ifstream in(path, std::ios::binary);
		if (!in) continue;
		return std::string(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
	}
	return Embedded(name);
}

std::filesystem::path DiskPath(std::string_view name)
{
	const auto relative = std::filesystem::path(INTERFACE_DATA_DIR) / std::string(name);
	std::error_code ec;
	if (std::filesystem::is_regular_file(relative, ec)) return relative;
	wchar_t exe[32768];
	const DWORD n = GetModuleFileNameW(nullptr, exe, _countof(exe));
	if (n && n < _countof(exe)) return std::filesystem::path(exe).parent_path() / INTERFACE_DATA_DIR / std::string(name);
	return relative;
}
}
